#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int largestSubmatrix(vector<vector<int>>& matrix) {
        int m = matrix.size();
        int n = matrix[0].size();
        vector<int> heights(n, 0);
        int ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (matrix[r][c] == 1) heights[c]++;
                else heights[c] = 0;
            }
            vector<int> sorted_h = heights;
            sort(sorted_h.rbegin(), sorted_h.rend());
            for (int i = 0; i < n; ++i) {
                ans = max(ans, sorted_h[i] * (i + 1));
            }
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int largestSubmatrix(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[] heights = new int[n];
        int ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (matrix[r][c] == 1) heights[c]++;
                else heights[c] = 0;
            }
            int[] sortedH = heights.clone();
            Arrays.sort(sortedH);
            for (int i = 0; i < n; ++i) {
                int h = sortedH[n - 1 - i];
                ans = Math.max(ans, h * (i + 1));
            }
        }
        return ans;
    }
}

