var largestSubmatrix = function(matrix) {
    const m = matrix.length;
    const n = matrix[0].length;
    const heights = Array(n).fill(0);
    let ans = 0;
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            if (matrix[r][c] === 1) heights[c]++;
            else heights[c] = 0;
        }
        const sortedH = [...heights].sort((a, b) => b - a);
        for (let i = 0; i < n; ++i) {
            ans = Math.max(ans, sortedH[i] * (i + 1));
        }
    }
    return ans;
};
